import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testExistingTeam() {
        val teams = mapOf(4215 to "Tribots", 1234 to "RoboCats")
        Assert.assertEquals("Tribots", lookupTeam(teams, 4215))
    }

    @Test
    fun testAnotherExistingTeam() {
        val teams = mapOf(4215 to "Tribots", 1234 to "RoboCats")
        Assert.assertEquals("RoboCats", lookupTeam(teams, 1234))
    }

    @Test
    fun testMissingTeam() {
        val teams = mapOf(4215 to "Tribots", 1234 to "RoboCats")
        Assert.assertEquals("Unknown", lookupTeam(teams, 9999))
    }

    @Test
    fun testEmptyMap() {
        val teams = mapOf<Int, String>()
        Assert.assertEquals("Unknown", lookupTeam(teams, 4215))
    }
}
